import{_ as i}from"./chunks/more.BA9dr6o4.js";import{_ as n,c as r,o as a,a2 as t}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"Weitere Vergleichsmöglichkeiten","description":"Vergleichen Sie Bilder und Archive, exportieren Sie einen Vergleich als Bild und passen Sie Darstellung und Sprache an.","frontmatter":{"title":"Weitere Vergleichsmöglichkeiten","description":"Vergleichen Sie Bilder und Archive, exportieren Sie einen Vergleich als Bild und passen Sie Darstellung und Sprache an."},"headers":[],"relativePath":"de/guide/more.md","filePath":"de/guide/more.md","lastUpdated":1794296122000}'),s={name:"de/guide/more.md"};function h(l,e,d,c,o,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="weitere-vergleichsmoglichkeiten" tabindex="-1">Weitere Vergleichsmöglichkeiten <a class="header-anchor" href="#weitere-vergleichsmoglichkeiten" aria-label="Permalink to &quot;Weitere Vergleichsmöglichkeiten&quot;">​</a></h1><p>Text ist nur ein Teil der Geschichte. qDiff öffnet mehrere andere Arten von Inhalten nach demselben Nebeneinander-Prinzip.</p><img src="'+i+'" alt="Zwei Bilder im Vergleich nebeneinander" class="guide-shot"><h2 id="bilder" tabindex="-1">Bilder <a class="header-anchor" href="#bilder" aria-label="Permalink to &quot;Bilder&quot;">​</a></h2><p>Stellen Sie zwei Bilder nebeneinander, um sie bequem zu vergleichen, oder legen Sie sie übereinander, um genau zu sehen, wo sie sich unterscheiden — praktisch bei Design-Überarbeitungen und fast identischen Fotos.</p><h2 id="komprimierte-archive" tabindex="-1">Komprimierte Archive <a class="header-anchor" href="#komprimierte-archive" aria-label="Permalink to &quot;Komprimierte Archive&quot;">​</a></h2><p>Ein .zip- oder .tar-Archiv lässt sich direkt öffnen und wie ein Ordner vergleichen. Kein Entpacken, keine temporären Dateien, die man hinterher aufräumen müsste.</p><h2 id="dateien-die-kein-reiner-text-sind" tabindex="-1">Dateien, die kein reiner Text sind <a class="header-anchor" href="#dateien-die-kein-reiner-text-sind" aria-label="Permalink to &quot;Dateien, die kein reiner Text sind&quot;">​</a></h2><p>Wenn zwei Dateien identisch aussehen, sich aber unterschiedlich verhalten, kann qDiff sie bis ins kleinste Detail vergleichen — einschließlich Unterschieden, die eine Textansicht nicht zeigen kann.</p><h2 id="einen-vergleich-als-bild-speichern" tabindex="-1">Einen Vergleich als Bild speichern <a class="header-anchor" href="#einen-vergleich-als-bild-speichern" aria-label="Permalink to &quot;Einen Vergleich als Bild speichern&quot;">​</a></h2><p>Wählen Sie eine Änderung aus und exportieren Sie sie als sauberes, zweispaltiges Bild — bereit zum Einfügen in eine Nachricht, ein Dokument oder ein Review. Dem Bild werden keine Hinweise hinzugefügt.</p><h2 id="ganz-nach-ihrem-geschmack" tabindex="-1">Ganz nach Ihrem Geschmack <a class="header-anchor" href="#ganz-nach-ihrem-geschmack" aria-label="Permalink to &quot;Ganz nach Ihrem Geschmack&quot;">​</a></h2><ul><li><strong>Darstellung</strong> — hell und dunkel, passend zu Ihrem Mac oder manuell eingestellt.</li><li><strong>Sprache</strong> — Englisch, vereinfachtes Chinesisch, traditionelles Chinesisch, Japanisch, Deutsch, Spanisch und Französisch.</li><li><strong>Schriften und Tastenkürzel</strong> — passen Sie den Lesekomfort an und nutzen Sie die Tastatur für die Aktionen, die Sie am häufigsten wiederholen.</li><li><strong>Kürzliche Vergleiche</strong> — öffnen Sie etwas, das Sie gestern angesehen haben, direkt vom Begrüßungsbildschirm erneut.</li></ul><p>All dies ist in der kostenlosen Version enthalten.</p><p>Noch eine Frage? <a href="./faq.html">Sehen Sie in die FAQ</a>.</p>',15)])])}const k=n(s,[["render",h]]);export{p as __pageData,k as default};
